import torch
import torch.nn as nn

class DeepMLP(nn.Module):

    def __init__(
        self,
        depth=10,
        width=128
    ):

        super().__init__()

        self.layers = nn.ModuleList([
            nn.Linear(width, width)
            for _ in range(depth)
        ])

    def forward(self, x):

        activation_stds = []

        for layer in self.layers:

            x = torch.relu(
                layer(x)
            )

            activation_stds.append(
                x.std(unbiased=False).item()
            )

        return x, activation_stds

def initialize_model(model, method):

    for layer in model.layers:

        if method == "small":

            nn.init.normal_(
                layer.weight,
                mean=0.0,
                std=0.01
            )

        elif method == "xavier":

            nn.init.xavier_normal_(
                layer.weight
            )

        elif method == "he":

            nn.init.kaiming_normal_(
                layer.weight,
                mode="fan_in",
                nonlinearity="relu"
            )

        else:

            raise ValueError(
                f"Unknown initialization: {method}"
            )

        nn.init.zeros_(
            layer.bias
        )

nn.init.xavier_uniform_(
